class Solution {
public:
    int minimumMoves(std::vector<int>& arr) {
        int n = arr.size();
        std::vector<std::vector<int>> dp(n, std::vector<int>(n, 0));
        for (int i = 0; i < n; ++i) dp[i][i] = 1;
        for (int i = 0; i < n - 1; ++i) dp[i][i + 1] = (arr[i] == arr[i + 1] ? 1 : 2);

        for (int len = 3; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                int res = (arr[i] == arr[j] ? dp[i + 1][j - 1] : 1e9);
                for (int k = i; k < j; ++k) {
                    res = std::min(res, dp[i][k] + dp[k + 1][j]);
                }
                dp[i][j] = res;
            }
        }
        return dp[0][n - 1];
    }
};

class Solution {
    public int minimumMoves(int[] arr) {
        int n = arr.length;
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) dp[i][i] = 1;
        for (int i = 0; i < n - 1; i++) dp[i][i + 1] = (arr[i] == arr[i + 1] ? 1 : 2);

        for (int len = 3; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                int res = (arr[i] == arr[j] ? dp[i + 1][j - 1] : Integer.MAX_VALUE);
                for (int k = i; k < j; k++) {
                    res = Math.min(res, dp[i][k] + dp[k + 1][j]);
                }
                dp[i][j] = res;
            }
        }
        return dp[0][n - 1];
    }
}

